-- LedgerPilot 001_init.sql
-- Core actors, shop profile, vendors and uploaded originals.
-- Money is always NUMERIC(14,2); IDs are UUIDs generated by Postgres.

-- gen_random_uuid() is built into PostgreSQL 13+. No extension is required,
-- which also keeps the embedded PostgreSQL development fallback working.

CREATE TABLE IF NOT EXISTS schema_migrations (
  version text PRIMARY KEY,
  applied_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS app_users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  display_name text NOT NULL CHECK (length(trim(display_name)) > 0),
  role text NOT NULL CHECK (role IN ('owner', 'staff', 'system', 'accountant')),
  email text NULL,
  initials text NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- The demo runs one shop. Keeping the profile in Postgres means the API and
-- every process see the same "as of" date and GSTIN.
CREATE TABLE IF NOT EXISTS business_settings (
  id text PRIMARY KEY DEFAULT 'primary' CHECK (id = 'primary'),
  name text NOT NULL,
  legal_name text NOT NULL,
  gstin text NOT NULL,
  address text NOT NULL,
  city text NOT NULL,
  state text NOT NULL,
  pincode text NOT NULL,
  phone text NOT NULL,
  email text NOT NULL,
  fy text NOT NULL,
  as_of timestamptz NOT NULL,
  bank_name text NOT NULL,
  bank_account_masked text NOT NULL,
  bank_ifsc text NOT NULL,
  bank_upi_id text NULL,
  bank_status text NOT NULL DEFAULT 'verified'
    CHECK (bank_status IN ('verified', 'changed')),
  force_next_failure boolean NOT NULL DEFAULT false,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS vendors (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL CHECK (length(trim(name)) > 0),
  category text NULL,
  gstin text NULL CHECK (gstin IS NULL OR gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$'),
  phone text NULL,
  email text NULL,
  address text NULL,
  city text NULL,
  state text NULL,
  pincode text NULL,
  terms_days integer NOT NULL DEFAULT 30 CHECK (terms_days BETWEEN 0 AND 365),
  terms_label text NULL,
  bank_name text NOT NULL DEFAULT 'SIMULATED BANK',
  bank_account_masked text NOT NULL DEFAULT '**** 0000',
  bank_ifsc text NOT NULL DEFAULT 'SIMU0000001',
  bank_upi_id text NULL,
  bank_status text NOT NULL DEFAULT 'verified'
    CHECK (bank_status IN ('verified', 'changed')),
  bank_changed_at timestamptz NULL,
  previous_account_masked text NULL,
  last_payment_date date NULL,
  status text NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'verify')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS vendors_name_uq ON vendors (lower(name));
CREATE INDEX IF NOT EXISTS vendors_status_idx ON vendors (status);

CREATE TABLE IF NOT EXISTS uploaded_files (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  original_filename text NOT NULL,
  stored_name text NOT NULL UNIQUE,
  content_type text NOT NULL
    CHECK (content_type IN ('application/pdf', 'image/png', 'image/jpeg')),
  size_bytes integer NOT NULL CHECK (size_bytes BETWEEN 1 AND 10485760),
  sha256 text NOT NULL,
  created_by uuid NOT NULL REFERENCES app_users(id),
  created_at timestamptz NOT NULL DEFAULT now()
);
